     1→import React, { useState, useRef, useEffect, useCallback } from "react";
     2→import { View, Text, StyleSheet, Alert } from "react-native";
     3→import { Button } from "react-native-paper";
     4→import MapView, { Marker, Polyline, PROVIDER_GOOGLE } from "react-native-maps";
     5→import { Route } from "../../types/Route";
     6→import {
     7→  useFrameCapture,
     8→  FrameCaptureOptions,
     9→} from "../../services/FrameCaptureService";
    10→import { VideoRecordingService } from "../../services/VideoRecordingService";
    11→import * as FileSystem from "expo-file-system";
    12→import * as MediaLibrary from "expo-media-library";
    13→
    14→// Constants
    15→const ANIMATION_SPEED = 3000; // 3000ms between waypoints
    16→const FRAME_CAPTURE_INTERVAL = 1000 / 30; // 30fps = ~33.33ms between frames
    17→const TOTAL_FRAMES_PER_WAYPOINT = 30; // 1 second of footage per waypoint
    18→
    19→// Types
    20→interface MapRegion {
    21→  latitude: number;
    22→  longitude: number;
    23→  latitudeDelta: number;
    24→  longitudeDelta: number;
    25→}
    26→
    27→interface Props {
    28→  route: Route;
    29→  onVideoCreated?: (videoUri: string) => void;
    30→  frameCaptureOptions?: Partial<FrameCaptureOptions>;
    31→}
    32→
    33→export const RecordableRouteMap: React.FC<Props> = ({
    34→  route,
    35→  onVideoCreated,
    36→  frameCaptureOptions,
    37→}) => {
    38→  // State
    39→  const [isRecording, setIsRecording] = useState(false);
    40→  const [processingVideo, setProcessingVideo] = useState(false);
    41→  const [recordingProgress, setRecordingProgress] = useState(0);
    42→  const [currentIndex, setCurrentIndex] = useState(0);
    43→  const [mapRegion, setMapRegion] = useState<MapRegion>({
    44→    latitude: route.waypoints[0]?.coordinate.latitude || 37.78825,
    45→    longitude: route.waypoints[0]?.coordinate.longitude || -122.4324,
    46→    latitudeDelta: 0.01,
    47→    longitudeDelta: 0.01,
    48→  });
    49→
    50→  // Refs
    51→  const mapRef = useRef<MapView>(null);
    52→  const videoServiceRef = useRef(
    53→    new VideoRecordingService({
    54→      fps: 30,
    55→      duration: 10,
    56→      quality: 0.9,
    57→    })
    58→  );
    59→  const intervalRef = useRef<NodeJS.Timeout | null>(null);
    60→  const frameCaptureIntervalRef = useRef<NodeJS.Timeout | null>(null);
    61→
    62→  // Use the new functional frame capture hook
    63→  const frameCapture = useFrameCapture(frameCaptureOptions);
    64→
    65→  // Calculate region that fits all waypoints
    66→  const getRouteRegion = useCallback((): MapRegion | null => {
    67→    if (route.waypoints.length === 0) return null;
    68→
    69→    const coordinates = route.waypoints.map((wp) => wp.coordinate);
    70→    const minLat = Math.min(...coordinates.map((c) => c.latitude));
    71→    const maxLat = Math.max(...coordinates.map((c) => c.latitude));
    72→    const minLng = Math.min(...coordinates.map((c) => c.longitude));
    73→    const maxLng = Math.max(...coordinates.map((c) => c.longitude));
    74→
    75→    const latDelta = (maxLat - minLat) * 1.2;
    76→    const lngDelta = (maxLng - minLng) * 1.2;
    77→
    78→    return {
    79→      latitude: (minLat + maxLat) / 2,
    80→      longitude: (minLng + maxLng) / 2,
    81→      latitudeDelta: Math.max(latDelta, 0.01),
    82→      longitudeDelta: Math.max(lngDelta, 0.01),
    83→    };
    84→  }, [route.waypoints]);
    85→
    86→  // Fit map to show entire route
    87→  const fitToRoute = useCallback(() => {
    88→    const region = getRouteRegion();
    89→    if (region && mapRef.current) {
    90→      mapRef.current.animateToRegion(region, 1000);
    91→    }
    92→  }, [getRouteRegion]);
    93→
    94→  // Animate to specific waypoint
    95→  const animateToWaypoint = useCallback(
    96→    (index: number, duration: number = 1000) => {
    97→      if (index >= route.waypoints.length) return;
    98→
    99→      const waypoint = route.waypoints[index];
   100→
   101→      if (mapRef.current) {
   102→        mapRef.current.animateToRegion(
   103→          {
   104→            latitude: waypoint.coordinate.latitude,
   105→            longitude: waypoint.coordinate.longitude,
   106→            latitudeDelta: 0.01,
   107→            longitudeDelta: 0.01,
   108→          },
   109→          duration
   110→        );
   111→
   112→        setMapRegion({
   113→          latitude: waypoint.coordinate.latitude,
   114→          longitude: waypoint.coordinate.longitude,
   115→          latitudeDelta: 0.01,
   116→          longitudeDelta: 0.01,
   117→        });
   118→      }
   119→    },
   120→    [route.waypoints]
   121→  );
   122→
   123→  // Capture a single frame
   124→  const captureFrame = useCallback(
   125→    async (index: number) => {
   126→      if (!frameCapture.isCapturing || !mapRef.current) {
   127→        return;
   128→      }
   129→
   130→      try {
   131→        const totalFrames = route.waypoints.length * TOTAL_FRAMES_PER_WAYPOINT;
   132→
   133→        const frame = await frameCapture.captureFrame(
   134→          mapRef.current,
   135→          index,
   136→          totalFrames
   137→        );
   138→
   139→        if (frame) {
   140→          setRecordingProgress((index + 1) / totalFrames);
   141→        }
   142→      } catch (error) {
   143→        console.error("Error capturing frame:", error);
   144→      }
   145→    },
   146→    [route.waypoints.length, frameCapture]
   147→  );
   148→
   149→  // Start frame capture and animation
   150→  const startFrameCapture = useCallback(async (): Promise<boolean> => {
   151→    try {
   152→      // Request media library permissions
   153→      const { status } = await MediaLibrary.requestPermissionsAsync();
   154→      if (status !== "granted") {
   155→        Alert.alert(
   156→          "Permission Required",
   157→          "Media library permission is needed to save frames"
   158→        );
   159→        return false;
   160→      }
   161→
   162→      await frameCapture.startCapture();
   163→
   164→      // Reset to start
   165→      setCurrentIndex(0);
   166→      let frameCount = 0;
   167→      const totalFrames = route.waypoints.length * TOTAL_FRAMES_PER_WAYPOINT;
   168→
   169→      // Start continuous frame capture at 30fps
   170→      frameCaptureIntervalRef.current = setInterval(async () => {
   171→        if (mapRef.current && frameCapture.isCapturing) {
   172→          await captureFrame(frameCount);
   173→          frameCount++;
   174→
   175→          // Stop if we've captured all frames
   176→          if (frameCount >= totalFrames) {
   177→            if (frameCaptureIntervalRef.current) {
   178→              clearInterval(frameCaptureIntervalRef.current);
   179→            }
   180→            if (intervalRef.current) {
   181→              clearInterval(intervalRef.current);
   182→            }
   183→            await stopFrameCapture();
   184→          }
   185→        }
   186→      }, FRAME_CAPTURE_INTERVAL);
   187→
   188→      // Start waypoint animation
   189→      intervalRef.current = setInterval(() => {
   190→        setCurrentIndex((prevIndex) => {
   191→          if (prevIndex < route.waypoints.length - 1) {
   192→            const newIndex = prevIndex + 1;
   193→            animateToWaypoint(newIndex, ANIMATION_SPEED);
   194→            return newIndex;
   195→          } else {
   196→            // Animation complete, wait 300ms before stopping
   197→            setTimeout(() => {
   198→              if (frameCaptureIntervalRef.current) {
   199→                clearInterval(frameCaptureIntervalRef.current);
   200→              }
   201→              if (intervalRef.current) {
   202→                clearInterval(intervalRef.current);
   203→              }
   204→              stopFrameCapture();
   205→            }, 300);
   206→            return prevIndex;
   207→          }
   208→        });
   209→      }, ANIMATION_SPEED);
   210→
   211→      return true;
   212→    } catch (error) {
   213→      console.error("Failed to start frame capture:", error);
   214→      return false;
   215→    }
   216→  }, [route.waypoints.length, animateToWaypoint, captureFrame, frameCapture]);
   217→
   218→  // Stop frame capture
   219→  const stopFrameCapture = useCallback(async (): Promise<any[]> => {
   220→    try {
   221→      const frames = await frameCapture.stopCapture();
   222→      return frames;
   223→    } catch (error) {
   224→      console.error("Failed to stop frame capture:", error);
   225→      return [];
   226→    }
   227→  }, [frameCapture]);
   228→
   229→  // Toggle recording
   230→  const toggleRecording = useCallback(async () => {
   231→    if (isRecording) {
   232→      await stopRecording();
   233→      return;
   234→    }
   235→
   236→    if (!route?.waypoints?.length) {
   237→      Alert.alert("Error", "No waypoints available to record");
   238→      return;
   239→    }
   240→
   241→    if (route.waypoints.length < 2) {
   242→      Alert.alert("Error", "Add at least 2 waypoints to record");
   243→      return;
   244→    }
   245→
   246→    try {
   247→      setIsRecording(true);
   248→      const success = await startFrameCapture();
   249→      if (!success) {
   250→        setIsRecording(false);
   251→        Alert.alert("Error", "Failed to start recording");
   252→      }
   253→    } catch (error) {
   254→      console.error("Error starting recording:", error);
   255→      setIsRecording(false);
   256→      Alert.alert("Recording Error", "Failed to start recording");
   257→    }
   258→  }, [isRecording, route.waypoints, startFrameCapture]);
   259→
   260→  // Stop recording and process video
   261→  const stopRecording = useCallback(async () => {
   262→    if (!isRecording) return;
   263→
   264→    try {
   265→      setProcessingVideo(true);
   266→
   267→      const frames = await stopFrameCapture();
   268→      console.log(`Captured ${frames.length} frames`);
   269→
   270→      if (frames.length > 0) {
   271→        // Create a video from the frames
   272→        const videoUri = await videoServiceRef.current.createVideoFromFrames(
   273→          frames
   274→        );
   275→
   276→        // Cleanup frames
   277→        await videoServiceRef.current.cleanupFrames(frames);
   278→
   279→        // Call the callback with the video URI
   280→        if (onVideoCreated) {
   281→          onVideoCreated(videoUri);
   282→        }
   283→
   284→        Alert.alert("Success", "Video created successfully!");
   285→      }
   286→    } catch (error) {
   287→      console.error("Video creation failed:", error);
   288→      Alert.alert("Error", "Failed to create video");
   289→    } finally {
   290→      setIsRecording(false);
   291→      setProcessingVideo(false);
   292→      setRecordingProgress(0);
   293→    }
   294→  }, [isRecording, onVideoCreated]);
   295→
   296→  // Cleanup on unmount
   297→  useEffect(() => {
   298→    return () => {
   299→      if (intervalRef.current) {
   300→        clearInterval(intervalRef.current);
   301→      }
   302→      if (frameCaptureIntervalRef.current) {
   303→        clearInterval(frameCaptureIntervalRef.current);
   304→      }
   305→      if (frameCapture.isCapturing) {
   306→        frameCapture.stopCapture().catch(console.error);
   307→      }
   308→    };
   309→  }, [frameCapture.isCapturing, frameCapture]);
   310→
   311→  // Debug logging
   312→  useEffect(() => {
   313→    console.log("Route data:", {
   314→      hasRoute: !!route,
   315→      waypointCount: route?.waypoints?.length || 0,
   316→      isRecording,
   317→      processingVideo,
   318→    });
   319→  }, [route, isRecording, processingVideo]);
   320→
   321→  if (route.waypoints.length === 0) {
   322→    return (
   323→      <View style={styles.emptyContainer}>
   324→        <Text>No waypoints in this route</Text>
   325→      </View>
   326→    );
   327→  }
   328→
   329→  return (
   330→    <View style={styles.container}>
   331→      <View style={styles.mapContainer}>
   332→        <MapView
   333→          ref={mapRef}
   334→          provider={PROVIDER_GOOGLE}
   335→          style={styles.map}
   336→          initialRegion={mapRegion}
   337→          showsUserLocation={false}
   338→          onLayout={fitToRoute}
   339→        >
   340→          {/* Polyline showing full route */}
   341→          <Polyline
   342→            coordinates={route.waypoints.map((wp) => wp.coordinate)}
   343→            strokeColor="#FF6B35"
   344→            strokeWidth={4}
   345→          />
   346→
   347→          {/* All waypoint markers */}
   348→          {route.waypoints.map((waypoint, index) => (
   349→            <Marker
   350→              key={waypoint.id}
   351→              coordinate={waypoint.coordinate}
   352→              title={waypoint.name || `Waypoint ${index + 1}`}
   353→              pinColor={index === currentIndex ? "red" : "blue"}
   354→            />
   355→          ))}
   356→
   357→          {/* Current position marker */}
   358→          {route.waypoints[currentIndex] && (
   359→            <Marker
   360→              coordinate={route.waypoints[currentIndex].coordinate}
   361→              anchor={{ x: 0.5, y: 0.5 }}
   362→            >
   363→              <View style={[styles.currentMarker, { opacity: 1 }]} />
   364→            </Marker>
   365→          )}
   366→        </MapView>
   367→      </View>
   368→
   369→      <View style={styles.buttonContainer}>
   370→        <Button
   371→          mode="contained"
   372→          onPress={toggleRecording}
   373→          disabled={processingVideo || !route?.waypoints?.length}
   374→          icon={isRecording ? "stop" : "video"}
   375→          style={[
   376→            styles.recordButton,
   377→            isRecording && { backgroundColor: "#ff4444" },
   378→          ]}
   379→        >
   380→          {processingVideo
   381→            ? "Processing..."
   382→            : isRecording
   383→            ? "Stop Recording"
   384→            : "Record Route"}
   385→        </Button>
   386→      </View>
   387→
   388→      {/* Recording progress indicator */}
   389→      {isRecording && (
   390→        <View style={styles.progressContainer}>
   391→          <Text style={styles.progressText}>
   392→            Recording: {Math.round(recordingProgress * 100)}%
   393→          </Text>
   394→          <Text style={styles.progressText}>
   395→            Frames: {frameCapture.capturedFrames.length}
   396→          </Text>
   397→        </View>
   398→      )}
   399→
   400→      {/* Error display */}
